def current_rows(events):
    latest = {}
    for e in events:
        eid = e['id']
        if eid not in latest or (e['event_time'], e['seq']) > (latest[eid]['event_time'], latest[eid]['seq']):
            latest[eid] = e
    return sorted(
        [{'id': k, 'value': v['value']} for k, v in latest.items() if v['op'] != 'D'],
        key=lambda x: x['id']
    )
